// Some portions generated by Claude
/**
 * Classes with many instances (Values on). Each instance's type link would be a spoke from the class card across the
 * drawing, while the card colours already say the type, so these links are collapsed: not drawn or routed, and shown
 * only for the cards the user points at or selects. The class card itself stays, placed among its instances.
 */
import { RDF_TYPE } from "./graph-canvas-scope.ts";
import type { Graph, GraphEdge } from "./graph-types.ts";

/** A class with at least this many drawn instances is a class hub. */
export const CLASS_HUB_MIN_INSTANCES = 6;

/** Classes that are the type of at least `CLASS_HUB_MIN_INSTANCES` nodes of this graph. */
export function classHubsOf(graph: Graph) {
  const instances = new Map<string, number>();
  for (const edge of graph.edges) if (edge.predicate === RDF_TYPE) instances.set(edge.target, (instances.get(edge.target) ?? 0) + 1);
  return new Set([...instances].filter(([, count]) => count >= CLASS_HUB_MIN_INSTANCES).map(([id]) => id));
}

export type CollapsedClassLinks = { graph: Graph; collapsed: readonly GraphEdge[] };
const collapsedGraphs = new WeakMap<Graph, CollapsedClassLinks>();

/** The graph without its links to class hubs (the same object when there are none), and those links. */
export function withCollapsedClassLinks(graph: Graph): CollapsedClassLinks {
  const known = collapsedGraphs.get(graph);
  if (known) return known;
  const hubs = classHubsOf(graph);
  const collapsed: GraphEdge[] = [];
  const edges = hubs.size
    ? graph.edges.filter((edge) => {
        const hide = edge.predicate === RDF_TYPE && hubs.has(edge.target);
        if (hide) collapsed.push(edge);
        return !hide;
      })
    : graph.edges;
  const result = { graph: collapsed.length ? { ...graph, edges } : graph, collapsed };
  collapsedGraphs.set(graph, result);
  return result;
}
